      "year": 107,
      "session": 1,
      "subject": "law",
      "sourceId": "law-01",
      "number": 28,
      "stem": "上市有價證券之買賣，應於證券交易所開設之有價證券集中交易市場為之，是為場外交易之禁止。下列敘述何者錯誤？",
