      "stem": "A 公司為上市公司，設有董事 7 人，其中3 人為獨立董事，並組成審計委員會。若 A 公司擬向其董事甲購買土地一筆，該議案於審計委員會討論時，未獲通過。依證券交易法規定，下列敘述何者正確？",
