      "session": 1,
      "subject": "law",
      "number": 2,
      "stem": "為提升公司治理，我國上市上櫃公司已全面要求設置獨立董事，惟獨立董事制度在運作上最大的 問題之一，在於其對公司所知之資訊有限。請問現行證券交易法有何規定可以強化獨立董事的資 訊權？(10分)",
