        "一、證券交易法第14條之2：公司不得妨礙、拒絕或規避獨立董事執行業務；獨立董事執行業務認有必要時，得要求董事會指派相關人員或自行聘請專家協助辦理，必要費用由公司負擔。",
        "二、證券交易法第14條之3：已選任獨立董事之公司，內部控制、重大資產或衍生性商品交易、重大資金貸與或背書、簽證會計師任免、財務會計或內部稽核主管任免等重大事項應提董事會決議，獨立董事反對或保留意見應載明於議事錄。",
        "三、證券交易法第14條之4與第14條之5：審計委員會由全體獨立董事組成並行使監察人職權；涉及董事自身利害關係、重大資產取得或處分、資金貸與、背書保證等事項，應經審計委員會同意，使獨立董事得以充分取得資訊並實質審查。",
        "四、公司法第218條調查業務及財務狀況、查核簿冊文件等監察人職權，準用於審計委員會獨立董事成員；獨立董事亦得依公司法第205條以視訊參與會議，並受證券交易法第25條持股申報等規範。"
