      "session": 2,
      "subject": "law",
      "number": 3,
      "stem": "2020 年 2 月下旬，因新冠肺炎疫情爆發，上市公司 A（下稱 A 公司）股價由 2 月 24 日 80.5 元 跌到 3 月 23 日 39.8 元。2020 年 3 月 15 日（星期日）17：00 媒體報導 A 公司跳票，並報導 A 公司自第 3 季財務報告有虛增營業收入之情事，虛增營收係由財務長與總經理主導。A 公司股 價於 2020 年 3 月 16 日之收盤價 50 元跌到 20 日收盤價 42 元，23 日開盤觸及 39.8 元後，隨即 反彈，自 16 日起十天之平均收盤價為 49 元。A 公司董事長甲於 2020 年 3 月 15 日晚餐時，看 見手機中媒體報導公司涉跳票及財報不實之情事，非常震驚，告訴其妻乙「公司居然發生虛增 營收財報不實的事情，真搞不清楚這些人為何如此經營公司？我真倒楣。」乙為財經系畢業，於 3 月 16 日開盤 9：00 以 55 元放空 A 公司股票 100 張，並於 3 月 18 日回補，獲利 30 萬元，3 月 16 日當天成交量為 3 萬張。請問本題中，甲及乙是否違反證券交易法？請分析之。（10 分）",
