        "甲部分：甲為A公司董事長，屬第157條之1第1項第1款的內部人。甲將重大消息告知乙，乙據以交易，依第157條之1第4項，甲原則上應與乙負連帶民事賠償責任；但甲能證明有正當理由相信消息已公開者，不負賠償責任。甲在3月15日17:00已看到媒體報導，可能主張相信消息已公開；然而媒體報導不等於公司經主管機關規定的公開程序，且18小時內仍禁止交易，甲仍可被認定為洩漏消息。",
