      "year": 111,
      "session": 2,
      "subject": "law",
      "number": 2,
      "stem": "A 公司所發行之股票自 2018 年 1 月起，於證券櫃檯買賣中心掛牌交易。A 公司之業務經理甲 為籌措女兒出國留學學費，擬於 2022 年 8 月出售其個人以及其妻子於 2022 年 3 月於公開交 易市場以每股新台幣 （下同）50 元所買進 100 張之 A 公司股票 （甲與其妻乙分別持有50 張）。請問根據證券交易法，甲欲出售此100 張 A 公司股票，出售前後應完成哪些程序始為完整合 法？ （10 分）",
