        "(一) 出售前：依證交法第22條之2，經理人轉讓股票應先向主管機關申報，並自申報之日起3日後，在集中交易市場或證券商營業處所為之；每一交易日轉讓股數未超過10,000股者，免予申報。本題擬出售100,000股，若集中於少數交易日，應先申報並遵守每日得轉讓數量比例；若分散至每日不超過10,000股，則可適用免申報，但仍受其他規定限制。",
        "(二) 出售後：依第25條，甲應於每月5日以前將上月份持股變動情形向公司申報，公司應於每月15日以前彙總向主管機關申報；持股變動包括本人及配偶部分。",
