        "即使6個月後X公司真的宣布將開始臨床實驗與合資，也不能回溯治癒甲在110年10月1日的不實陳述；證券交易法評價的是行為當時的言論是否虛偽、有無合理根據，而非事後是否成真。且X公司後來用的是「將開始進行」，與甲所稱「已開始進行」不同。",
