      "year": 112,
      "session": 2,
      "subject": "law",
      "number": 1,
      "stem": "A 公司申請股票上市時，在公開說明書中所附之財務報表內，列有不實之現金科目，造成其財報主 要內容有虛偽不實之記載，上市一年半後，A 公司發生顯著之財務危機，公司支票不兌現金額達新 台幣五億元，致A 公司股票價格暴跌，A 公司投資人B 持股產生重大損失，然A 公司負責人及重 要幹部等均前往海外洽公不知去向，股東投訴無門。B 乃控告A 公司及其簽證會計師C，請求損害 賠償。試問：(10 分) （1）A 公司應否負擔賠償 B 股東持股損害之責任？其理由為何？ （2）會計師 C 在何種情況下，可行使證券交易法上之免責抗辯？",
