        "一、大量取得股份申報門檻由10%降為5%：任何人單獨或與他人共同取得任一公開發行公司已發行股份總額超過5%之股份者，應向主管機關申報及公告；申報事項有變動時亦同。第43條之1自公布後一年施行，給予實務配套調整期間。",
