        "基層員工指非屬經理人且薪資水準低於一定金額者。提撥比率得採固定數、一定區間或下限方式訂定，並得於公司法第235條之1員工酬勞範圍內定之；調整薪資或分派酬勞得擇一或併行。前項調整薪資或分派酬勞之金額，得自當年度營利事業所得額減除。金管會要求上市櫃公司於114年股東會完成章程修訂，114年度起適用。",
