      "stem": "X 上櫃公司於 115 年 3 月下旬公告該公司 114 年度財務報告，業績表現亮麗，獲利高於同業，吸引不少投資人進場購買該公司股票，惟 114 年度財務報告中有虛偽不實交易及不實現金科目 之情事，115 年 6 月底該公司資金週轉困難，公司支票發生退票事宜，消息揭露後，X 公司股票 連跌數日，投資人因信賴該公司製作之不實財報，蒙受巨大損失。試問：依證券交易法規定，X 公司 114 年度財務報告不實，其賠償義務人及責任型態為何？（10 分）",
